/// One term's contribution to a competitor's fitness, in fixed point.
///
/// Integer arithmetic throughout: this is read by the optional win
/// probability victory condition from inside the synchronised simulation, so
/// every platform has to reach the same answer bit for bit.
inline Sint64 winProbabilityTermFixed(const std::vector<Slot> &slots, std::size_t index, int term)
{
	const Slot &slot = slots[index];
	switch (term)
	{
	case 0: // units (share)
	{
		Sint64 total = 0;
		for (std::size_t i = 0; i < slots.size(); ++i)
			if (slots[i].alive)
				total += clampCount(slots[i].units);
		return (WIN_PROBABILITY_UNITS_SHARE_FIXED * shareValue(slot.units, total)) >> FRACTION_SHIFT;
	}
	case 1: // prestige (identity)
		return WIN_PROBABILITY_PRESTIGE_IDENTITY_FIXED * countValue(slot.prestige);
	case 2: // barracks (sqrt)
		return (WIN_PROBABILITY_BARRACKS_SQRT_FIXED * rootValue(slot.barracks)) >> ROOT_SHIFT;
	case 3: // explorers (sqrt)
		return (WIN_PROBABILITY_EXPLORERS_SQRT_FIXED * rootValue(slot.explorers)) >> ROOT_SHIFT;
	case 4: // starving_ratio (identity)
		return (WIN_PROBABILITY_STARVING_RATIO_IDENTITY_FIXED * ratioValue(slot.foodCritical, slot.units)) >> FRACTION_SHIFT;
	case 5: // attack (share)
	{
		Sint64 total = 0;
		for (std::size_t i = 0; i < slots.size(); ++i)
			if (slots[i].alive)
				total += clampCount(slots[i].attack);
		return (WIN_PROBABILITY_ATTACK_SHARE_FIXED * shareValue(slot.attack, total)) >> FRACTION_SHIFT;
	}
	}
	return 0;
}

/// A competitor's fitness, given every competitor still standing.
inline Sint64 winProbabilityFitness(const std::vector<Slot> &slots, std::size_t index)
{
	Sint64 fitness = WIN_PROBABILITY_INTERCEPT_FIXED;
	for (int term = 0; term < WIN_PROBABILITY_FEATURE_COUNT; ++term)
		fitness += winProbabilityTermFixed(slots, index, term);
	return fitness;
}

/// What one term measures, before its coefficient: the number the
/// breakdown shows next to the term. Display only, so plain arithmetic.
inline double winProbabilityMeasurement(const std::vector<Slot> &slots, std::size_t index, int term)
{
	const Slot &slot = slots[index];
	switch (term)
	{
	case 0:
	{
		double total = 0;
		for (std::size_t i = 0; i < slots.size(); ++i)
			if (slots[i].alive)
				total += double(slots[i].units);
		return total > 0 ? double(slot.units) / total : 0.0;
	}
	case 1:
		return double(slot.prestige);
	case 2:
		return double(slot.barracks);
	case 3:
		return double(slot.explorers);
	case 4:
		return slot.units > 0 ? double(slot.foodCritical) / double(slot.units) : 0.0;
	case 5:
	{
		double total = 0;
		for (std::size_t i = 0; i < slots.size(); ++i)
			if (slots[i].alive)
				total += double(slots[i].attack);
		return total > 0 ? double(slot.attack) / total : 0.0;
	}
	}
	return 0;
}

/// That term's share of the fitness, as a readable number. Display only.
inline double winProbabilityContribution(const std::vector<Slot> &slots, std::size_t index, int term)
{
	return double(winProbabilityTermFixed(slots, index, term)) / double(FITNESS_ONE);
}
